import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

template <typename T>
__device__ __forceinline__ float to_float(T x);
template <>
__device__ __forceinline__ float to_float<float>(float x) { return x; }
template <>
__device__ __forceinline__ float to_float<at::Half>(at::Half x) { return __half2float(x); }
template <>
__device__ __forceinline__ float to_float<at::BFloat16>(at::BFloat16 x) { return __bfloat162float(x); }

template <typename T>
__device__ __forceinline__ T from_float(float x);
template <>
__device__ __forceinline__ float from_float<float>(float x) { return x; }
template <>
__device__ __forceinline__ at::Half from_float<at::Half>(float x) { return __float2half_rn(x); }
template <>
__device__ __forceinline__ at::BFloat16 from_float<at::BFloat16>(float x) { return __float2bfloat16(x); }

__device__ __forceinline__ float sigmoidf_fast(float x) {
    return 1.0f / (1.0f + __expf(-x));
}

template <typename scalar_t>
__global__ void swiglu_kernel(
    const scalar_t* __restrict__ a,
    const scalar_t* __restrict__ b,
    scalar_t* __restrict__ c,
    int64_t N,
    int64_t D,
    int64_t stride_a0,
    int64_t stride_b0,
    int64_t stride_c0
) {
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t total = N * D;
    for (int64_t linear = idx; linear < total; linear += (int64_t)gridDim.x * blockDim.x) {
        int64_t row = linear / D;
        int64_t col = linear - row * D;
        int64_t oa = row * stride_a0 + col;
        int64_t ob = row * stride_b0 + col;
        int64_t oc = row * stride_c0 + col;
        float av = to_float<scalar_t>(a[oa]);
        float bv = to_float<scalar_t>(b[ob]);
        float silu = av * sigmoidf_fast(av);
        c[oc] = from_float<scalar_t>(silu * bv);
    }
}

torch::Tensor swiglu_forward(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.is_cuda(), "a must be CUDA");
    TORCH_CHECK(b.is_cuda(), "b must be CUDA");
    TORCH_CHECK(a.scalar_type() == b.scalar_type(), "dtype mismatch");
    TORCH_CHECK(a.dim() == 2 && b.dim() == 2, "inputs must be 2D");
    TORCH_CHECK(a.sizes() == b.sizes(), "shape mismatch");
    auto c = torch::empty_like(a);

    const auto N = a.size(0);
    const auto D = a.size(1);
    const int threads = 256;
    const int64_t total = N * D;
    int blocks = (int)((total + threads - 1) / threads);
    blocks = blocks > 65535 ? 65535 : blocks;
    auto stream = at::cuda::getDefaultCUDAStream();

    AT_DISPATCH_FLOATING_TYPES_AND2(at::Half, at::BFloat16, a.scalar_type(), "swiglu_forward_cuda", [&] {
        swiglu_kernel<scalar_t><<<blocks, threads, 0, stream>>>(
            a.data_ptr<scalar_t>(),
            b.data_ptr<scalar_t>(),
            c.data_ptr<scalar_t>(),
            N, D,
            a.stride(0),
            b.stride(0),
            c.stride(0)
        );
    });
    return c;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("forward", &swiglu_forward, "swiglu forward");
}
'''

_mod = None

def _ext():
    global _mod
    if _mod is None:
        _mod = load_inline(
            name='swiglu_h100_ext',
            cpp_sources='',
            cuda_sources=_src,
            functions=None,
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            verbose=False,
        )
    return _mod

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, a: torch.Tensor, b: torch.Tensor) -> torch.Tensor:
        return _ext().forward(a, b)
